channels.--ds-card-transition:
background-color var(--ds-card-transition-duration)
      var(--ds-card-transition-timing),
    border-color var(--ds-card-transition-duration)
      var(--ds-card-transition-timing),
    color var(--ds-card-transition-duration) var(--ds-card-transition-timing),
    box-shadow var(--ds-card-transition-duration)
      var(--ds-card-transition-timing),
    transform var(--ds-card-transition-duration)
      var(--ds-card-transition-timing)

channels.--ds-chart-panel-bg:
linear-gradient(
    145deg,
    var(--ds-surface-card-bg),
    color-mix(in srgb, var(--ds-color-secondary) 4%, var(--ds-surface-panel-bg))
  )

channels.--ds-command-grid-bg:
linear-gradient(
      var(--ds-command-grid-line-soft) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      var(--ds-command-grid-line-soft) 1px,
      transparent 1px
    )

channels.--ds-command-grid-bg-strong:
linear-gradient(
      var(--ds-command-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(90deg, var(--ds-command-grid-line) 1px, transparent 1px)

channels.--ds-command-home-card-bg:
linear-gradient(
      90deg,
      color-mix(in srgb, var(--ds-command-home-card-tone) 6%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ds-command-home-card-tone) 4%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      180deg,
      var(--ds-surface-card-bg),
      var(--ds-surface-panel-bg)
    )

channels.--ds-command-home-card-shadow:
var(
    --ds-surface-card-shadow,
    var(
      --ds-card-shadow,
      0 1px 2px color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent)
    )
  )

channels.--ds-command-home-card-shadow-hover:
var(
    --ds-surface-card-shadow-hover,
    var(
      --ds-card-shadow-hover,
      0 2px 6px color-mix(in srgb, var(--ds-color-text-primary) 8%, transparent)
    )
  )

channels.--ds-command-home-console-bg:
repeating-linear-gradient(
      90deg,
      var(--ds-command-home-grid-line) 0 1px,
      transparent 1px 30px
    ),
    repeating-linear-gradient(
      0deg,
      var(--ds-command-home-grid-line) 0 1px,
      transparent 1px 30px
    ),
    var(--ds-workspace-shell-overlay, transparent),
    linear-gradient(
      180deg,
      color-mix(
          in srgb,
          var(--ds-surface-card-bg) 96%,
          var(--ds-color-primary) 4%
        )
        0%,
      color-mix(
          in srgb,
          var(--ds-surface-panel-bg) 72%,
          var(--ds-surface-card-bg)
        )
        100%
    )

channels.--ds-command-home-grid-line:
var(
    --ds-command-grid-line-soft,
    var(
      --ds-shell-command-grid-line-soft,
      color-mix(in srgb, var(--ds-color-primary) 8%, transparent)
    )
  )

channels.--ds-command-home-hero-bg:
repeating-linear-gradient(
      90deg,
      var(--ds-command-home-grid-line) 0 1px,
      transparent 1px 28px
    ),
    repeating-linear-gradient(
      0deg,
      var(--ds-command-home-grid-line) 0 1px,
      transparent 1px 28px
    ),
    var(
      --ds-premium-card-bg,
      linear-gradient(
        180deg,
        var(--ds-surface-card-bg) 0%,
        color-mix(
            in srgb,
            var(--ds-surface-panel-bg) 50%,
            var(--ds-surface-card-bg)
          )
          100%
      )
    )

channels.--ds-command-home-icon-border:
var(
    --ds-surface-icon-border,
    color-mix(
      in srgb,
      var(--ds-color-primary) 24%,
      var(--ds-color-border-primary)
    )
  )

channels.--ds-command-home-panel-bg:
var(
    --ds-premium-card-bg,
    linear-gradient(
      180deg,
      var(--ds-surface-card-bg) 0%,
      color-mix(
          in srgb,
          var(--ds-surface-panel-bg) 56%,
          var(--ds-surface-card-bg)
        )
        100%
    )
  )

channels.--ds-command-home-panel-bg-strong:
linear-gradient(
    180deg,
    var(--ds-surface-card-bg) 0%,
    color-mix(
        in srgb,
        var(--ds-surface-panel-bg) 32%,
        var(--ds-surface-card-bg)
      )
      100%
  )

channels.--ds-command-home-panel-border:
color-mix(
    in srgb,
    var(--ds-color-primary) 20%,
    var(--ds-color-border-secondary, var(--ds-color-border-primary))
  )

channels.--ds-command-home-panel-shadow:
var(
    --ds-command-glow,
    0 1px 2px color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent),
    0 16px 42px color-mix(in srgb, var(--ds-color-primary) 7%, transparent)
  )

channels.--ds-command-home-surface-bg:
repeating-linear-gradient(
      90deg,
      var(--ds-command-home-grid-line) 0 1px,
      transparent 1px 26px
    ),
    repeating-linear-gradient(
      0deg,
      var(--ds-command-home-grid-line) 0 1px,
      transparent 1px 26px
    ),
    var(
      --ds-command-rail-bg,
      linear-gradient(
        180deg,
        var(--ds-surface-card-bg) 0%,
        color-mix(
            in srgb,
            var(--ds-surface-panel-bg) 58%,
            var(--ds-surface-card-bg)
          )
          100%
      )
    )

channels.--ds-empty-state-bg:
linear-gradient(
    145deg,
    color-mix(in srgb, var(--ds-color-primary) 5%, var(--ds-surface-card-bg)),
    var(--ds-surface-panel-bg)
  )

channels.--ds-error-state-bg:
linear-gradient(
    145deg,
    color-mix(in srgb, var(--ds-color-error) 7%, var(--ds-surface-card-bg)),
    var(--ds-surface-panel-bg)
  )

channels.--ds-premium-card-bg-active:
var(
    --ds-material-card-background-active,
    color-mix(
      in srgb,
      var(--ds-color-primary) 7%,
      var(--ds-material-card-background, var(--ds-card-bg))
    )
  )

channels.--ds-premium-card-bg-disabled:
var(
    --ds-material-card-background-disabled,
    color-mix(
      in srgb,
      var(--ds-material-card-background, var(--ds-card-bg)) 82%,
      var(--ds-surface-panel-bg)
    )
  )

channels.--ds-premium-card-bg-hover:
var(
    --ds-material-card-background-hover,
    color-mix(
      in srgb,
      var(--ds-color-primary) 4%,
      var(--ds-material-card-background, var(--ds-card-bg-hover))
    )
  )

channels.--ds-premium-card-bg-selected:
var(
    --ds-material-card-background-selected,
    color-mix(
      in srgb,
      var(--ds-color-primary) 9%,
      var(--ds-material-card-background, var(--ds-card-bg))
    )
  )

channels.--ds-premium-card-border-hover:
var(
    --ds-material-card-border-hover,
    color-mix(
      in srgb,
      var(--ds-color-primary) 24%,
      var(--ds-material-card-border-strong, var(--ds-card-border-color))
    )
  )

channels.--ds-premium-card-disabled-border:
var(
    --ds-material-card-border-disabled,
    color-mix(
      in srgb,
      var(--ds-material-card-border, var(--ds-card-border-color)) 58%,
      transparent
    )
  )

channels.--ds-premium-card-glass-bg:
color-mix(
    in srgb,
    var(--ds-material-card-background, var(--ds-card-bg)) 86%,
    transparent
  )

channels.--ds-premium-card-grid-bg:
linear-gradient(
      var(--ds-premium-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      var(--ds-premium-card-grid-line) 1px,
      transparent 1px
    )

channels.--ds-premium-card-selected-border:
var(
    --ds-material-card-border-selected,
    color-mix(
      in srgb,
      var(--ds-color-primary) 46%,
      var(--ds-material-card-border-strong, var(--ds-card-border-color))
    )
  )

channels.--ds-premium-card-shadow-selected:
var(
    --ds-material-card-shadow-selected,
    var(
      --ds-material-card-focus-ring,
      0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 12%, transparent)
    )
  )

channels.--ds-skeleton-wave-gradient:
linear-gradient(
    90deg,
    var(--ds-surface-panel-bg) 25%,
    color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-surface-card-bg)) 50%,
    var(--ds-surface-panel-bg) 75%
  )

channels.--ds-surface-card-grid-bg:
linear-gradient(
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      115deg,
      transparent 0%,
      color-mix(in srgb, var(--ds-surface-card-bg) 34%, transparent) 46%,
      transparent 66%
    )

channels.--ds-surface-hero-bg:
linear-gradient(
    145deg,
    var(--ds-surface-card-bg),
    color-mix(in srgb, var(--ds-color-primary) 6%, var(--ds-surface-panel-bg))
  )

channels.--ds-table-action-bg:
linear-gradient(
    90deg,
    color-mix(in srgb, var(--ds-table-bg) 60%, transparent),
    var(--ds-table-bg)
  )

channels.--ds-transition-card:
transform var(--ds-motion-feedback)
      var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-feedback) var(--ds-motion-ease-out)

channels.--transition-modal-content:
opacity var(--duration-normal)
      var(--easing-standard),
    transform var(--duration-normal) var(--easing-emphasized)
